const EMBEDDED_ASSETS = {"/app.js":["text/javascript; charset=utf-8",""],"/biscuit.jpg":["image/jpeg",""],"/geo-map.css":["text/css; charset=utf-8",""],"/geo-map.js":["text/javascript; charset=utf-8",""],"/index.html":["text/html; charset=utf-8",""],"/map-art.js":["text/javascript; charset=utf-8",""],"/mochi.jpg":["image/jpeg",""],"/pixel-cats.css":["text/css; charset=utf-8",""],"/pixel-cats.js":["text/javascript; charset=utf-8",""],"/pudding.jpg":["image/jpeg",""],"/shadow.jpg":["image/jpeg",""],"/styles.css":["text/css; charset=utf-8",""]};
